import { ChangeDetectorRef, Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { HttpClient } from '@angular/common/http';
import { ZApi } from '../shared-ui/z-api';

/** Skeleton of a level 4 module page (standalone component, ZApi adds ?schema=). */
@Component({
  selector: 'z-acme',
  standalone: true,
  imports: [CommonModule, FormsModule],
  styleUrls: ['../expense/expense.css', '../zeo-apps/za.css'],
  template: `
<div class="container"><div class="comapny_section">
  <div class="header_section"><div class="ex-head"><div><h1 class="page-title">Acme requests</h1></div>
    <div class="ex-actions"><button type="button" class="ex-btn primary" (click)="add()">New request</button></div></div></div>
  <div class="com_list mt-4"><p class="hs-note err" *ngIf="err">{{ err }}</p>
    <table class="hs-table" zPlain><tr><th>No.</th><th>Title</th><th>Amount</th><th>Status</th></tr>
      <tr *ngFor="let r of rows"><td>{{ r.number }}</td><td>{{ r.title }}</td><td>{{ r.amount }}</td><td>{{ r.status }}</td></tr></table></div>
</div></div>`,
})
export class AcmeComponent implements OnInit {
  api: ZApi; rows: any[] = []; err = '';
  constructor(http: HttpClient, private cd: ChangeDetectorRef) { this.api = new ZApi(http); }
  async ngOnInit(): Promise<void> { try { const d: any = await this.api.get('acme/api/requests/'); this.rows = d.results || d; } catch (e) { this.err = ZApi.err(e); } this.cd.markForCheck(); }
  add(): void { /* open a form – see hr26/custom26.component.ts for the pattern */ }
}

