from rest_framework import serializers

from .models import AcmeRequest


class AcmeRequestSerializer(serializers.ModelSerializer):
    class Meta:
        model = AcmeRequest
        fields = ['id', 'number', 'employee', 'title', 'amount', 'status', 'created_at']
        read_only_fields = ['number', 'status', 'created_at']

    def validate_amount(self, v):
        if v < 0:
            raise serializers.ValidationError('The amount cannot be negative.')
        return v
